-- Generated by `make db-migration` from schema.prisma. Review before applying.
-- Explicit transaction: Prisma does not make migrations atomic on PostgreSQL.
-- Hand-written SQL (RLS policies, CHECK constraints, functions) goes ABOVE the final COMMIT.
BEGIN;

-- Hand-written migration: no schema.prisma change (Prisma cannot model expression indexes).
-- Full-text search over message bodies (ADR 0013 decision 7). The search query must use exactly this expression,
-- to_tsvector('simple', body), for the planner to use the index; it narrows by conversation first (BitmapAnd).
-- Measured on 250k messages: 1.2 s → 11 ms for a rare term across 400 visible channels.
CREATE INDEX "messages_body_fts_idx" ON "messages" USING gin (to_tsvector('simple', body));

COMMIT;
